const products=[
{id:'wide',name:'Jeans Wide Leg',type:'Calças',wash:'Azul médio',image:'wide.webp',description:'Modelagem ampla de cintura alta e caimento estruturado.'},
{id:'reta',name:'Jeans Reta',type:'Calças',wash:'Índigo escuro',image:'reta.webp',description:'Corte reto clássico em lavagem índigo escura.'},
{id:'short',name:'Short Jeans',type:'Shorts',wash:'Azul claro',image:'short.webp',description:'Short jeans de cintura alta com barra dobrada.'}
];
const main=document.querySelector('main'),dialog=document.querySelector('#cart-dialog');let cart=[];try{cart=JSON.parse(localStorage.getItem('ms-prototype-cart-v1')||'[]').filter(x=>typeof x.id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(x.id)&&typeof x.size==='string'&&/^(PP|P|M|G|GG|XG|XGG|[3-6][0-9])$/.test(x.size)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99)}catch{cart=[]}let filter='Todos',query='',sort='default',selectedSize='',quantity=1,toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(kind)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v11M7 5l10 4"/>',person:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-4a7 7 0 0 1 14 0v4"/>',truck:'<path d="M2 5h12v12H2ZM14 10h4l4 4v3h-8"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',card:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20M6 15h4"/>'})[kind]}</svg>`;
const card=p=>`<article class="product-card"><a class="product-image" href="#produto/${p.id}"><img src="${productImage(p.image)}" alt="${esc(p.name)} — ${esc(p.wash)}" loading="lazy" decoding="async"></a><div class="product-info"><div class="meta"><span>${esc(p.type.toUpperCase())} · ${esc(p.wash.toUpperCase())}</span><span class="swatch" aria-label="${esc(p.wash)}"><span style="background:${p.id==='reta'?'#253d56':p.id==='short'?'#9bb9cc':'#577f9d'}"></span></span></div><h3><a href="#produto/${p.id}">${esc(p.name)}</a></h3><div class="product-bottom"><span class="stock-summary">${stockSummary(p)}</span><a href="#produto/${p.id}">Ver grade</a></div></div></article>`;
const defaultHero={eyebrow:'ATACADO EM LAJEADO · RS',headline:'Sua próxima vitrine',highlight:'começa aqui.',subtitle:'Jeans de giro rápido para abastecer sua loja perto de você.',ctaText:'VER CATÁLOGO',ctaHref:'#catalogo',image:'/assets/hero.webp'};let hero={...defaultHero};
const faqs=[['Precisa ter CNPJ para comprar?','Não. Você compra com CPF ou CNPJ a partir de 6 peças.'],['As 6 peças podem ser variadas?','Sim. Misture modelos e tamanhos como preferir.'],['Como funciona a entrega?','Entregamos na região. Consulte frete e prazo com a equipe.'],['Quais são as formas de pagamento?','Pix ou cartão em até 12x, com taxa por conta do cliente.']];
const faq=()=>faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">${esc(hero.eyebrow)}</div><h1>${esc(hero.headline)}<br><span>${esc(hero.highlight)}</span></h1><p>${esc(hero.subtitle)}</p><a class="btn" href="${esc(hero.ctaHref)}">${esc(hero.ctaText)}</a></div><div class="hero-photo"><img fetchpriority="high" src="${esc(hero.image)}" alt="${esc(hero.headline)}"><div class="hero-label"><strong>06</strong><div>PEÇAS NO MÍNIMO<small>Modelos e tamanhos variados</small></div></div></div></section>${benefitsStrip()}<section class="wrap section"><div class="section-head"><div><div class="eyebrow">COLEÇÃO</div><h2>Destaques da vitrine</h2></div><a class="text-link" href="#catalogo">Ver todo o catálogo</a></div><div class="grid">${products.map(card).join('')}</div></section><section class="wholesale" id="atacado"><div><div class="eyebrow">COMO FUNCIONA</div><h2>Você escolhe.<br>A gente abastece.</h2><a href="#como-comprar" class="btn dark">COMO COMPRAR</a></div><div class="steps"><div class="step"><span>01</span><div><h3>Escolha os modelos</h3><p>Confira as peças e a numeração disponível.</p></div></div><div class="step"><span>02</span><div><h3>Monte 6 peças</h3><p>Misture modelos e tamanhos com CPF ou CNPJ.</p></div></div><div class="step"><span>03</span><div><h3>Feche seu pedido</h3><p>Combine pagamento e entrega com a equipe.</p></div></div></div></section><section class="wrap section faq-layout"><div><div class="eyebrow">DÚVIDAS</div><h2>Perguntas<br>frequentes</h2><a class="text-link" href="#atendimento">Falar com a equipe</a></div><div>${faq()}</div></section><section class="store-banner"><div><div class="eyebrow">LOJA FÍSICA</div><h2>Centro · Lajeado/RS</h2><p>Rua Fialho de Vargas, 49 · Sala 101</p></div><a class="btn outline" href="#loja">VER ENDEREÇO</a></section>`}
function catalog(){return `<div class="wrap section"><div class="catalog-heading"><div class="crumb"><a href="#inicio">Início</a> / Catálogo</div><h1>Catálogo</h1></div><div class="catalog-controls"><div class="tabs" aria-label="Categoria">${['Todos',...categoryNames()].map(t=>`<button data-filter="${esc(t)}" class="${filter===t?'active':''}" aria-pressed="${filter===t}">${esc(t)}</button>`).join('')}</div><label>Ordenar <select id="sort"><option value="default">Destaques</option><option value="az" ${sort==='az'?'selected':''}>Nome: A–Z</option></select></label></div><p class="muted" id="result-count"></p><div id="products" class="grid"></div></div>`}
function product(p){return `<div class="wrap section"><div class="crumb"><a href="#inicio">Início</a> / <a href="#catalogo">Catálogo</a> / ${esc(p.name)}</div><div class="product-page"><div class="detail-photo">${productGallery(p)}</div><div class="product-detail"><div class="eyebrow">${esc(p.type)} · ${esc(p.wash)}</div><h1>${esc(p.name)}</h1><p class="product-desc">${esc(p.description)}</p><span class="select-label">Tamanho</span><div class="sizes" role="group" aria-label="Tamanhos disponíveis">${sizeChoices(p)}</div><div class="purchase-row"><div class="quantity"><button data-qty="-1" aria-label="Diminuir quantidade" ${p.variants?.some(v=>v.quantity>0)?'':'disabled'}>−</button><input id="product-qty" aria-label="Quantidade de peças" type="number" inputmode="numeric" min="1" max="99" step="1" value="1" ${p.variants?.some(v=>v.quantity>0)?'':'disabled'}><button data-qty="1" aria-label="Aumentar quantidade" ${p.variants?.some(v=>v.quantity>0)?'':'disabled'}>+</button></div><button class="btn dark" data-add="${p.id}" ${p.variants?.some(v=>v.quantity>0)?'':'disabled'}>${p.variants?.some(v=>v.quantity>0)?'Adicionar ao pedido':'Indisponível'}</button></div><div class="hint">Pedido mínimo de <b>6 peças variadas</b> · CPF ou CNPJ · Pix ou até 12x</div></div></div></div>`}
function info(type){if(type==='loja')return `<section class="info-page"><div class="eyebrow">LOJA FÍSICA</div><h1>Visite a MS em Lajeado</h1><p>Conheça as peças de perto e monte o pedido para a sua loja.</p><div class="info-box"><h2>Endereço</h2><p>Rua Fialho de Vargas, 49 · Sala 101<br>Centro · Lajeado/RS</p></div><a class="btn" href="#atendimento">FALAR NO WHATSAPP</a></section>`;if(type==='atendimento')return `<section class="info-page"><div class="eyebrow">ATENDIMENTO</div><h1>Fale com a equipe</h1><p>Tire dúvidas sobre grade, valores e entrega na sua cidade.</p><div class="contact-options"><div class="info-box"><h2>WhatsApp</h2><p>(51) 99618-0830</p><a class="btn" href="https://wa.me/5551996180830" target="_blank" rel="noopener">CHAMAR NO WHATSAPP</a></div><div class="info-box"><h2>Loja física</h2><p>Rua Fialho de Vargas, 49 · Sala 101<br>Centro · Lajeado/RS</p><a class="btn outline" href="#loja">VER LOCALIZAÇÃO</a></div></div></section>`;return `<section class="info-page"><div class="eyebrow">COMO COMPRAR</div><h1>Atacado a partir de 6 peças</h1><p>Compre com CPF ou CNPJ misturando modelos e numerações.</p>${faq()}<div class="info-box"><h2>Passo a passo</h2><ol><li>Escolha os modelos e tamanhos na grade.</li><li>Complete o mínimo de 6 peças variadas.</li><li>Salve seu pedido e combine pagamento e entrega.</li></ol></div><a class="btn" href="#catalogo">VER CATÁLOGO</a></section>`}
function renderProducts(){let list=products.filter(p=>(filter==='Todos'||p.type===filter)&&(!query||(p.name+' '+p.wash).toLowerCase().includes(query.toLowerCase())));if(sort==='az')list.sort((a,b)=>a.name.localeCompare(b.name));document.querySelector('#products').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h2>Nenhum modelo encontrado</h2><p>Tente outro termo ou limpe os filtros.</p><button class="btn" data-clear>Limpar filtros</button></div>`;document.querySelector('#result-count').textContent=`${list.length} ${list.length===1?'modelo':'modelos'}${query?' para “'+query+'”':''}`;}
function route(){const [route,params]=(location.hash.slice(1)||'inicio').split('?');if(route==='catalogo'){const sp=new URLSearchParams(params);filter=sp.get('tipo')||'Todos';if(!['Todos',...categoryNames()].includes(filter))filter='Todos';query=sp.get('busca')||'';document.querySelector('#search').value=query;main.innerHTML=catalog();renderProducts()}else if(route.startsWith('produto/')){selectedSize='';quantity=1;const p=products.find(p=>p.id===route.split('/')[1]);main.innerHTML=p?product(p):'<section class="info-page"><h1>Produto não encontrado</h1><a class="btn" href="#catalogo">Voltar ao catálogo</a></section>'}else if(['loja','como-comprar','atendimento'].includes(route)){main.innerHTML=info(route)}else main.innerHTML=home();document.title=`MS Atacado — ${route==='inicio'?'Sua loja abastecida. Perto de você.':route.startsWith('produto/')?'Detalhes do produto':route==='catalogo'?'Catálogo':'Conheça a MS'}`;window.scrollTo(0,0)}
function save(){try{localStorage.setItem('ms-prototype-cart-v1',JSON.stringify(cart))}catch{}document.querySelector('#cart-count').textContent=cart.reduce((s,x)=>s+x.qty,0)}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2600)}
function renderCart(){const n=cart.reduce((s,x)=>s+x.qty,0);document.querySelector('#cart-body').innerHTML=!n?`<div class="empty"><h3>Sua sacola está vazia</h3><p>Monte seu pedido com pelo menos 6 peças variadas.</p><button class="btn" data-shop>Ver catálogo</button></div>`:`<div class="hint">${n>=6?'Mínimo atingido · '+n+' peças':'Faltam '+(6-n)+' peças para o mínimo de 6'}<div class="progress"><span style="width:${Math.min(n/6*100,100)}%"></span></div></div>${cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-line"><img src="${productImage(p.image)}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p>Tamanho ${esc(x.size)}</p>${x.qty>availableStock(x.id,x.size)?'<p class="stock-warning">Acima do estoque disponível</p>':''}<div class="cart-line-actions"><div class="quantity"><button data-cart-change="${i}" data-delta="-1" aria-label="Diminuir ${esc(p.name)}, tamanho ${x.size}">−</button><span>${x.qty}</span><button data-cart-change="${i}" data-delta="1" aria-label="Aumentar ${esc(p.name)}, tamanho ${x.size}">+</button></div><button class="remove" data-remove="${i}">Remover</button></div></div></div>`}).join('')}<div class="cart-summary"><div class="summary-row"><span>Total</span><b>${n} peças</b></div><button class="btn dark" data-review ${n<6?'disabled':''}>Continuar pedido</button></div>`}
document.querySelector('#open-cart').onclick=()=>{renderCart();dialog.showModal()};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#search-form').onsubmit=e=>{e.preventDefault();location.hash='catalogo?busca='+encodeURIComponent(document.querySelector('#search').value.trim());if(location.hash.slice(1)==='catalogo?busca=')route()};
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;renderProducts()}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-close'))dialog.close();if(el.hasAttribute('data-shop')){dialog.close();location.hash='catalogo'}if(el.hasAttribute('data-filter')){filter=el.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)});renderProducts()}if(el.hasAttribute('data-clear')){query='';filter='Todos';location.hash='catalogo';route()}if(el.hasAttribute('data-size')){selectedSize=el.dataset.size;document.querySelectorAll('[data-size]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)})}if(el.hasAttribute('data-qty')){quantity=Math.max(1,Math.min(99,quantity+Number(el.dataset.qty)));document.querySelector('#product-qty').value=quantity}if(el.hasAttribute('data-add')){if(!selectedSize){toast('Escolha um tamanho para continuar.');document.querySelector('[data-size]:not(:disabled)')?.focus();return}const match=cart.find(x=>x.id===el.dataset.add&&x.size===selectedSize);if(match)match.qty=Math.min(99,match.qty+quantity);else cart.push({id:el.dataset.add,size:selectedSize,qty:quantity});save();toast(quantity+' peça'+(quantity===1?' adicionada':'s adicionadas')+' ao pedido.')}if(el.hasAttribute('data-cart-change')){const i=Number(el.dataset.cartChange);cart[i].qty=Math.min(99,cart[i].qty+Number(el.dataset.delta));cart=cart.filter(x=>x.qty>0);save();renderCart()}if(el.hasAttribute('data-remove')){cart.splice(Number(el.dataset.remove),1);save();renderCart()}if(el.hasAttribute('data-review')){const n=cart.reduce((s,x)=>s+x.qty,0);if(n<6)return;document.querySelector('#cart-body').innerHTML=`<div class="success"><h3>Pedido pronto para revisão</h3><p>Você selecionou ${n} peças.</p></div><button class="btn" data-back-cart>Voltar ao pedido</button>`}if(el.hasAttribute('data-back-cart'))renderCart()});
window.addEventListener('hashchange',route);save();
